const Modal = forwardRef(function Modal({ children }, ref) {
  const [open, setOpen] = useState(false);

  useImperativeHandle(ref, () => ({
    open: () => setOpen(true),
    close: () => setOpen(false),
  }));

  if (!open) return null;
  return <div role="dialog">{children}</div>;
});

