import { forwardRef, useImperativeHandle, useRef, useState, useDebugValue } from 'react';

// PART 1: TextInput with custom imperative API
const TextInput = forwardRef(function TextInput({ label, ...props }, ref) {
  const inputRef = useRef(null);

  // TODO: useImperativeHandle to expose { focus, clear, getValue }
  // focus: focuses the input
  // clear: sets value to ''
  // getValue: returns current value

  return (
    <div>
      {label && <label>{label}</label>}
      <input data-testid="text-input" ref={inputRef} {...props} />
    </div>
  );
});

// PART 2: Counter hook factory
function createCounterHook(min = 0, max = Infinity, step = 1) {
  return function useCounter(initial = min) {
    const [count, setCount] = useState(Math.max(min, Math.min(max, initial)));

    // TODO: add useDebugValue showing current count

    const increment = () => setCount(c => Math.min(max, c + step));
    const decrement = () => setCount(c => Math.max(min, c - step));
    const reset = () => setCount(Math.max(min, initial));

    return { count, increment, decrement, reset };
  };
}

const useXpCounter = createCounterHook(0, 1000, 50);

export default function App() {
  const inputRef = useRef(null);
  const { count, increment, decrement, reset } = useXpCounter(100);

  return (
    <div>
      <TextInput ref={inputRef} label="Quest Title" defaultValue="" />
      <button data-testid="focus-btn" onClick={() => inputRef.current?.focus()}>Focus</button>
      <button data-testid="clear-btn" onClick={() => inputRef.current?.clear()}>Clear</button>

      <div data-testid="xp-display">XP: {count}</div>
      <button data-testid="inc-btn" onClick={increment}>+50 XP</button>
      <button data-testid="dec-btn" onClick={decrement}>-50 XP</button>
      <button data-testid="reset-btn" onClick={reset}>Reset</button>
    </div>
  );
}
